3	/**
4	 * The single definition of an owner's <em>identity key</em>: the derived value that decides
5	 * whether two owners are the same person for duplicate detection. It joins the normalized
6	 * telephone, the email (or empty) and the household id (or empty) with {@code '|'} so that a
7	 * duplicate is an exact match on the <em>whole</em> key — the same telephone alone, or the
8	 * same household alone, is not enough.
9	 *
10	 * <p>Shared by the create-owner reject step (which compares a request against existing owners)
11	 * and the response mapper (which returns the key), so both derive it identically.
12	 */
13	public final class OwnerIdentity {
14	
15	    private OwnerIdentity() {
16	    }
17	
18	    /**
19	     * The identity key {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId
20	     * or empty)}. The telephone and email are expected already normalized (E.164 / lower-cased)
21	     * by the create pipeline; a null part contributes an empty string.
22	     */
23	    public static String key(String telephone, String email, String householdId) {
24	        return part(telephone) + '|' + part(email) + '|' + part(householdId);
25	    }
26	
27	    /** The identity key of a stored owner, derived from its telephone, email and household id. */
28	    public static String of(Owner owner) {
29	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
30	    }
31	
32	    private static String part(String value) {
33	        return value == null ? "" : value;
34	    }
35	}
