31	            return; // no postcode to share, so no soft match
32	        }
33	        Owner match = null;
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (lastName.equals(canonical(existing.getLastName()))
36	                    && postcode.equals(trimmed(existing.getPostcode()))
37	                    && !Objects.equals(telephone, trimmed(existing.getTelephone()))
