9	
10	/**
11	 * Flags a soft duplicate: a create that is not a hard duplicate (see
12	 * {@link RejectDuplicateOwnerIdentity}, which already let it through) but that shares an
13	 * existing owner's last name and postcode while carrying a <em>different</em> telephone. The
14	 * owner is still created; the response merely carries {@code possibleDuplicate}/
15	 * {@code possibleDuplicateOf} pointing at the matched owner.
16	 *
17	 * <p>Runs after {@link BuildOwner} but before the owner is saved, so it compares against the
18	 * owners that existed before this create (and so never matches the owner being built), and
19	 * mutates the built {@link Owner} in place. When several owners match, the one with the lowest
20	 * id is reported, so the result is deterministic. Last names are compared case-insensitively
21	 * (as elsewhere, e.g. {@link AssignOwnerNamesakeCount}); postcode and telephone are compared in
22	 * their stored, normalized form.
23	 */
24	public class AssignOwnerPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String lastName = canonical(owner.getLastName());
28	        String postcode = trimmed(owner.getPostcode());
29	        String telephone = trimmed(owner.getTelephone());
30	        if (postcode == null) {
31	            return; // no postcode to share, so no soft match
32	        }
33	        Owner match = null;
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (lastName.equals(canonical(existing.getLastName()))
36	                    && postcode.equals(trimmed(existing.getPostcode()))
37	                    && !Objects.equals(telephone, trimmed(existing.getTelephone()))
38	                    && (match == null || existing.getId() < match.getId())) {
39	                match = existing;
40	            }
41	        }
42	        if (match != null) {
43	            owner.setPossibleDuplicateOf(match.getId());
44	        }
45	    }
46	
47	    private static String canonical(String value) {
48	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
49	    }
50	
51	    private static String trimmed(String value) {
52	        if (value == null) {
53	            return null;
54	        }
55	        String trimmed = value.trim();
56	        return trimmed.isEmpty() ? null : trimmed;
57	    }
58	}
